from solution import first


def test_issue_example_given():
    """Issue example: first([1,2,3,4,5,6,6],6,6) == 5."""
    assert first([1, 2, 3, 4, 5, 6, 6], 6, 6) == 5  # hand calc: 6-1=5, first 6 at index 5


def test_issue_first_element_at_start():
    """Issue: find the first position of an element in a sorted array at index 0."""
    assert first([1, 2, 3, 4, 5], 1, 5) == 0  # hand calc: 1-1=0, first element -> index 0


def test_issue_last_element_unique():
    """Issue: find the first position of the last unique element in a sorted array."""
    assert first([1, 2, 3, 4, 5], 5, 5) == 4  # hand calc: 5-1=4, last index is 4


def test_issue_duplicates_at_start():
    """Issue: find the first position when duplicates are at the start."""
    assert first([2, 2, 2, 3, 4], 2, 5) == 0  # hand calc: 1-1=0, first 2 at index 0


def test_issue_duplicates_in_middle():
    """Issue: find the first position when duplicates are in the middle."""
    assert first([1, 2, 3, 3, 3, 4, 5], 3, 7) == 2  # hand calc: 3-1=2, first 3 at index 2


def test_issue_single_element_found():
    """Issue: find the first position in a single-element sorted array."""
    assert first([10], 10, 1) == 0  # hand calc: 1-1=0, only element at index 0


def test_issue_missing_between_values():
    """Issue: find the first position returns -1 when value is missing between elements."""
    assert first([1, 2, 4, 5], 3, 4) == -1  # hand calc: 0-1=-1, 3 not present so -1


def test_issue_missing_below_minimum():
    """Issue: find the first position returns -1 when value is below the minimum."""
    assert first([5, 6, 7], 1, 3) == -1  # hand calc: 0-1=-1, 1 not present so -1


def test_issue_missing_above_maximum():
    """Issue: find the first position returns -1 when value is above the maximum."""
    assert first([1, 2, 3], 9, 3) == -1  # hand calc: 0-1=-1, 9 not present so -1


def test_issue_empty_array():
    """Issue: find the first position in an empty sorted array returns -1."""
    assert first([], 5, 0) == -1  # hand calc: 0-1=-1, empty so -1


def test_contract_repeated_calls_agree():
    """Contract: first(arr, x, n) is deterministic for the same inputs."""
    assert first([1, 2, 2, 3, 4], 2, 5) == first([1, 2, 2, 3, 4], 2, 5) == 1  # hand calc: 2-1=1, first 2 at index 1


def test_contract_leaves_input_unchanged():
    """Contract: first(arr, x, n) must not mutate the input array."""
    arr = [1, 2, 2, 3]
    assert (first(arr, 2, 4), arr) == (1, [1, 2, 2, 3])  # hand calc: 2-1=1, first 2 at index 1
